'use strict';

function fieldId(label) {
  return label
    .replace(/[^a-zA-Z0-9\s]/g, '')
    .trim()
    .split(/\s+/)
    .filter(Boolean)
    .map((w, i) => (i === 0 ? w.toLowerCase() : w[0].toUpperCase() + w.slice(1).toLowerCase()))
    .join('');
}

function fields(labels) {
  return labels.map((label) => ({ id: fieldId(label), label }));
}

function tab(id, label, fieldLabels, opts = {}) {
  return {
    id,
    label,
    kind: opts.kind || 'table',
    fields: fields(fieldLabels),
  };
}

