const SCHEMA_BY_ID = Object.fromEntries(REPORT_SCHEMAS.map((s) => [s.id, s]));

function getReportSchema(reportId) {
  return SCHEMA_BY_ID[reportId] || null;
}

function findTabByLabel(schema, sheetLabel) {
  return schema?.tabs.find((t) => t.label === sheetLabel) || null;
}

function catalogFromSchemas() {
  return REPORT_SCHEMAS.map((report) => ({
    id: report.id,
    title: report.title,
    description: report.description,
    status: 'ready',
    tabs: report.tabs.map((t) => ({
      id: t.id,
      label: t.label,
      kind: t.kind,
      fields: t.fields.map((f) => ({ id: f.id, label: f.label })),
    })),
  }));
}

module.exports = {
  REPORT_SCHEMAS,
  getReportSchema,
  findTabByLabel,
  catalogFromSchemas,
  fieldId,
};
